    discard: [
      "tool calls exploratórias já resolvidas",
      "conteúdo de arquivos lidos mas não modificados",
      "tentativas falhadas depois corrigidas",
    ],
  });

  session.replaceHistory(summary);
  // continua a tarefa sem o usuário perceber
}
